mapper.select:
select a.alliance_order_id as allianceOrderId, a.source_member_id as sourceMemberId, a.target_member_id as targetMemberId, a.transfer_mode as transferMode, a.alliance_order_status as allianceOrderStatus, a.masked_snapshot_json as maskedSnapshotJson, a.accepted_time as acceptedTime, a.create_time as createTime, a.remark, o.order_no as orderNo, o.create_time as orderCreateTime, a.create_time as transferTime, coalesce(json_unquote(json_extract(o.package_details_json, '$.packageName')), json_unquote(json_extract(a.masked_snapshot_json, '$.packageName'))) as packageName, o.lease_start_date as leaseStartDate, o.lease_end_date as leaseEndDate, o.rent_amount as rentAmount, o.deposit_amount as depositAmount, a.settlement_price as settlementPrice, target_warehouse.warehouse_name as targetWarehouseName, oi.quantity as quantity, coalesce((select l.carrier from ry_business.ry_rental_logistics_order l where l.order_id = a.child_order_id and l.member_id = a.target_member_id and l.direction = 1 and l.is_delete = 0 order by l.create_time desc, l.logistics_id desc limit 1), (select l.carrier from ry_business.ry_rental_logistics_order l where l.order_id = a.source_order_id and l.member_id = a.source_member_id and l.direction = 1 and l.is_delete = 0 order by l.create_time desc, l.logistics_id desc limit 1)) as shippingCarrier, coalesce((select l.tracking_no from ry_business.ry_rental_logistics_order l where l.order_id = a.child_order_id and l.member_id = a.target_member_id and l.direction = 1 and l.is_delete = 0 order by l.create_time desc, l.logistics_id desc limit 1), (select l.tracking_no from ry_business.ry_rental_logistics_order l where l.order_id = a.source_order_id and l.member_id = a.source_member_id and l.direction = 1 and l.is_delete = 0 order by l.create_time desc, l.logistics_id desc limit 1)) as shippingTrackingNo, coalesce((select l.carrier from ry_business.ry_rental_logistics_order l where l.order_id = a.child_order_id and l.member_id = a.target_member_id and l.direction = 2 and l.is_delete = 0 order by l.create_time desc, l.logistics_id desc limit 1), (select l.carrier from ry_business.ry_rental_logistics_order l where l.order_id = a.source_order_id and l.member_id = a.source_member_id and l.direction = 2 and l.is_delete = 0 order by l.create_time desc, l.logistics_id desc limit 1)) as returnCarrier, coalesce((select l.tracking_no from ry_business.ry_rental_logistics_order l where l.order_id = a.child_order_id and l.member_id = a.target_member_id and l.direction = 2 and l.is_delete = 0 order by l.create_time desc, l.logistics_id desc limit 1), (select l.tracking_no from ry_business.ry_rental_logistics_order l where l.order_id = a.source_order_id and l.member_id = a.source_member_id and l.direction = 2 and l.is_delete = 0 order by l.create_time desc, l.logistics_id desc limit 1)) as returnTrackingNo, coalesce((select l.route_status from ry_business.ry_rental_logistics_order l where l.order_id = a.child_order_id and l.member_id = a.target_member_id and l.direction = 1 and l.is_delete = 0 order by l.create_time desc, l.logistics_id desc limit 1), (select l.route_status from ry_business.ry_rental_logistics_order l where l.order_id = a.source_order_id and l.member_id = a.source_member_id and l.direction = 1 and l.is_delete = 0 order by l.create_time desc, l.logistics_id desc limit 1)) as shippingRouteStatus, coalesce((select l.route_status from ry_business.ry_rental_logistics_order l where l.order_id = a.child_order_id and l.member_id = a.target_member_id and l.direction = 2 and l.is_delete = 0 order by l.create_time desc, l.logistics_id desc limit 1), (select l.route_status from ry_business.ry_rental_logistics_order l where l.order_id = a.source_order_id and l.member_id = a.source_member_id and l.direction = 2 and l.is_delete = 0 order by l.create_time desc, l.logistics_id desc limit 1)) as returnRouteStatus from ry_business.ry_rental_order_alliance a left join ry_business.ry_rental_order o on o.order_id = a.source_order_id and o.tenant_id = a.tenant_id and o.member_id = a.source_member_id and o.is_delete = 0 left join ry_business.ry_rental_order_item oi on oi.order_id = o.order_id and oi.tenant_id = o.tenant_id and oi.member_id = o.member_id and oi.is_delete = 0 and oi.order_item_id = ( select min(first_item.order_item_id) from ry_business.ry_rental_order_item first_item where first_item.order_id = o.order_id and first_item.tenant_id = o.tenant_id and first_item.member_id = o.member_id and first_item.is_delete = 0 ) left join ry_business.ry_rental_warehouse target_warehouse on target_warehouse.warehouse_id = a.target_warehouse_id and target_warehouse.tenant_id = a.tenant_id and target_warehouse.member_id = a.target_member_id and target_warehouse.is_delete = 0 where a.tenant_id = #{tenantId} and (a.source_member_id = #{memberId} or a.target_member_id = #{memberId}
or (a.target_member_id is null and a.source_member_id in #{id} and a.source_member_id <> #{memberId} ) ) and a.is_delete = 0 and a.alliance_order_status = #{status}
and a.target_member_id = #{memberId}
and a.target_member_id is null and a.alliance_order_status = #{publicPoolStatus} and a.source_member_id in #{id} and a.source_member_id <> #{memberId}
and (o.order_no like concat('%', #{keyword}, '%') or json_unquote(json_extract(o.package_details_json, '$.packageName')) like concat('%', #{keyword}, '%') or json_unquote(json_extract(a.masked_snapshot_json, '$.modelName')) like concat('%', #{keyword}, '%'))
and json_unquote(json_extract(a.masked_snapshot_json, '$.deliveryCity')) like concat('%', #{deliveryCity}, '%')
and o.lease_start_date = #{leaseStartDate} order by a.create_time desc, a.alliance_order_id desc

select count(1) as totalCount,
       coalesce(sum(case when a.alliance_order_status = #{pendingStatus} then 1 else 0 end), 0) as pendingCount,
       coalesce(sum(case when a.alliance_order_status in (#{acceptedStatus}, #{fulfillmentStatus}) then 1 else 0 end), 0) as fulfillmentCount,
       coalesce(sum(case when a.alliance_order_status = #{completedStatus} then 1 else 0 end), 0) as completedCount,
       coalesce(sum(case when a.alliance_order_status = #{publicPoolStatus} then 1 else 0 end), 0) as publicPoolCount,
       coalesce(sum(case when a.alliance_order_status = #{publicPoolStatus}
           and a.create_time >= current_date
           and a.create_time < date_add(current_date, interval 1 day) then 1 else 0 end), 0) as todayNewCount,
       (select count(1) from ry_business.ry_rental_order_alliance accepted
        where accepted.tenant_id = #{tenantId} and accepted.target_member_id = #{memberId}
          and accepted.alliance_order_status in (#{acceptedStatus}, #{fulfillmentStatus})
          and accepted.is_delete = 0) as myAcceptedCount
from ry_business.ry_rental_order_alliance a
where a.tenant_id = #{tenantId} and a.is_delete = 0


    and a.target_member_id = #{memberId}


    and a.target_member_id is null and a.alliance_order_status = #{publicPoolStatus}
    and a.source_member_id in
    #{id}
    and a.source_member_id <> #{memberId}



    and (a.source_member_id = #{memberId} or a.target_member_id = #{memberId}

        or (a.target_member_id is null and a.alliance_order_status = #{publicPoolStatus}
          and a.source_member_id in
          #{id}
          and a.source_member_id <> #{memberId}
          )
      )

mapper.update:
update ry_business.ry_rental_order_alliance
set target_member_id = #{targetMemberId}, update_by = #{operatorId}, update_time = now()
where tenant_id = #{tenantId} and alliance_order_id = #{allianceOrderId}
  and target_member_id = #{currentMemberId}
  and alliance_order_status = 0 and is_delete = 0

update ry_business.ry_rental_order_alliance
set alliance_order_status = 3, update_by = #{operatorId}, update_time = now()
where tenant_id = #{tenantId} and alliance_order_id = #{allianceOrderId}
  and source_member_id = #{memberId}
  and alliance_order_status in (0, 5) and is_delete = 0

update ry_business.ry_rental_order_alliance
set alliance_order_status = #{toStatus}, update_by = #{operatorId}, update_time = now()
where alliance_order_id = #{allianceOrderId}
and tenant_id = #{tenantId}
  and alliance_order_status = #{fromStatus} and is_delete = 0
